package com.solace.mi;
import java.util.Map;
import java.nio.charset.StandardCharsets;
public final class Core {
 public byte[] process(byte[] payload, Map<String,Object> headers) {
   String text=new String(payload,StandardCharsets.UTF_8);
   if(text.isBlank()) throw new IllegalArgumentException("Empty input");
   return text.toUpperCase(java.util.Locale.ROOT).getBytes(StandardCharsets.UTF_8);
 }
}

